192	                ? ClaimStatus.PENDING : to;
193	        return rollup.tracking(sheetId, user, () -> {
194	            Person person = person(sheetId, claim.getPersonId());
195	            if (becomes == ClaimStatus.SETTLED) {
196	                // Settling fixes the due at what it is now, while the claim is still open (the figure a
197	                // statement bound it to, if any, and its late charge); later changes to rates, the
198	                // late percent and the sheet's today do not alter it.
199	                claim.setSettledDue(dues.figure(sheetId, person, claim));
200	            }
201	            // A void claim keeps the number it had (never reused).
202	            claim.setStatus(becomes);
203	            if (becomes == ClaimStatus.OPEN) {
204	                claim.setNumber(nextNumber(sheetId, claim.getDueBy()));
205	                claim.setOpenedBy(user);
206	            }
207	            logStatus(sheetId, user, person, claim);
208	            Claim saved = claims.saveAndFlush(claim);
209	            String event = switch (becomes) {
210	                case OPEN -> "CLAIM_OPENED";
211	                case PENDING -> "CLAIM_PENDING";
212	                case SETTLED -> "CLAIM_SETTLED";
213	                case VOID -> "CLAIM_VOIDED";
214	                case DRAFT -> throw new IllegalStateException("a claim never returns to DRAFT");
215	            };
216	            String line = record(event, sheetId, user, person, saved);
217	            if (becomes == ClaimStatus.SETTLED) {
218	                line += " due=" + dueText(saved.getSettledDue());
219	            }
220	            audit.recordOnCommit(line);
221	            if (becomes == ClaimStatus.SETTLED) {
222	                watches.notifyWatchers(sheetId, user, person, saved.getNumber());
223	            }
224	            return saved;
225	        });
226	    }
