278	    /** Raise a claim's proofs count by one. Refused when the claim is settled or void, or its period
279	     *  is closed. It changes no figure. */
280	    @Transactional
281	    public Claim addProof(String sheetId, String user, long claimId) {
282	        Claim claim = lock(sheetId, claimId);
283	        refuseClosed(sheetId, claim.getDueBy());
284	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
285	            throw new ResponseStatusException(HttpStatus.CONFLICT,
286	                    "A " + claim.getStatus() + " claim cannot be given a proof");
287	        }
288	        Person person = person(sheetId, claim.getPersonId());
289	        claim.addProof();
290	        Claim saved = claims.saveAndFlush(claim);
291	        audit.recordOnCommit(record("CLAIM_PROOF_ADDED", sheetId, user, person, saved) + " proofs=" + saved.getProofs());
292	        return saved;
293	    }
