295	    /** Approve a pending claim: it becomes settled, its due fixed at the figure it has now (its live
296	     *  figure and late charge). Refused unless the claim is pending, the user is a steward and is not
297	     *  the one who opened it, the claim's period is open, and it has a proof if it needs one. */
298	    @Transactional
299	    public Claim approve(String sheetId, String user, long claimId) {
300	        Claim claim = lockPending(sheetId, user, claimId);
301	        if (user.equals(claim.getOpenedBy())) {
302	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
303	                    "The user who opened a claim cannot approve it");
304	        }
305	        refuseUnproved(sheetId, claim);
306	        return rollup.tracking(sheetId, user, () -> {
307	            Person person = person(sheetId, claim.getPersonId());
308	            claim.setSettledDue(dues.figure(sheetId, person, claim));
309	            claim.setStatus(ClaimStatus.SETTLED);
310	            logStatus(sheetId, user, person, claim);
311	            Claim saved = claims.saveAndFlush(claim);
312	            audit.recordOnCommit(record("CLAIM_APPROVED", sheetId, user, person, saved)
313	                    + " due=" + dueText(saved.getSettledDue()));
314	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
315	            return saved;
316	        });
317	    }
