319	    /** Re-settle a settled claim: its due is fixed again at the figure it would have today as an open
320	     *  claim bound by no statement (today's rates, grades, floor and late charge). Refused unless the
321	     *  claim is settled, the user is a steward, and the claim's period is open. */
322	    @Transactional
323	    public Claim resettle(String sheetId, String user, long claimId) {
324	        Claim claim = lock(sheetId, claimId);
325	        refuseClosed(sheetId, claim.getDueBy());
326	        if (claim.getStatus() != ClaimStatus.SETTLED) {
327	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled");
328	        }
329	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
330	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-settle a claim");
331	        }
332	        return rollup.tracking(sheetId, user, () -> {
333	            Person person = person(sheetId, claim.getPersonId());
334	            BigDecimal old = dues.figure(sheetId, person, claim);
335	            BigDecimal now = dues.openFigure(sheetId, person, claim);
336	            claim.setSettledDue(now);
337	            claim.logStatus(user, sheets.today(sheetId), now);
338	            Claim saved = claims.saveAndFlush(claim);
339	            audit.recordOnCommit(record("CLAIM_RESETTLED", sheetId, user, person, saved)
340	                    + " old=" + dueText(old) + " new=" + dueText(now));
341	            watches.notifyWatchers(sheetId, user, person, saved.getNumber());
342	            return saved;
343	        });
344	    }
