346	    /** Reject a pending claim for a reason: it is open again, bound again by its person's last
347	     *  statement if that statement included it. Refused unless the claim is pending, the user is a
348	     *  steward, and the claim's period is open. */
349	    @Transactional
350	    public Claim reject(String sheetId, String user, long claimId, String reason) {
351	        Claim claim = lockPending(sheetId, user, claimId);
352	        return rollup.tracking(sheetId, user, () -> {
353	            Person person = person(sheetId, claim.getPersonId());
354	            claim.setStatus(ClaimStatus.OPEN);
355	            logStatus(sheetId, user, person, claim);
356	            Claim saved = claims.saveAndFlush(claim);
357	            audit.recordOnCommit(record("CLAIM_REJECTED", sheetId, user, person, saved) + " reason=" + reason);
358	            return saved;
359	        });
360	    }
