362	    /** Move a draft, open or pending claim to another person on the sheet. It keeps its number, date
363	     *  and status, loses any figure a statement bound it to, and is listed as its new person's newest
364	     *  claim. Refused unless the permission matrix allows the user's role to reassign, and when the claim is settled or void, the person
365	     *  is the one it is already for, the claim's period is closed, or the claim is dated after the
366	     *  new person's retirement day. */
367	    @Transactional
368	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
369	        Claim claim = lock(sheetId, claimId);
370	        if (!roles.may(sheetId, user, "reassign")) {
371	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
372	        }
373	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
374	            throw new ResponseStatusException(HttpStatus.CONFLICT,
375	                    "A " + claim.getStatus() + " claim cannot be reassigned");
376	        }
377	        if (claim.getPersonId() == toPersonId) {
378	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's");
379	        }
380	        refuseClosed(sheetId, claim.getDueBy());
381	        Person from = person(sheetId, claim.getPersonId());
382	        Person to = person(sheetId, toPersonId);
383	        refuseRetired(to, claim.getDate());
384	        return rollup.tracking(sheetId, user, () -> {
385	            claim.moveTo(to.getId(), claims.nextListed());
386	            Claim saved = claims.saveAndFlush(claim);
387	            audit.recordOnCommit(record("CLAIM_REASSIGNED", sheetId, user, to, saved)
388	                    + " from=" + from.getName() + " to=" + to.getName());
389	            return saved;
390	        });
391	    }
