393	    /** Re-date an open or pending claim: it keeps the due-by it was fixed with, and so its period and
394	     *  number, and any figure a statement bound it to. Refused unless the user is a steward, and when
395	     *  the claim is not open or pending, its period is closed, or the new date is after the person's
396	     *  retirement day. */
397	    @Transactional
398	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
399	        Claim claim = lock(sheetId, claimId);
400	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
401	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can re-date a claim");
402	        }
403	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
404	            throw new ResponseStatusException(HttpStatus.CONFLICT,
405	                    "A " + claim.getStatus() + " claim cannot be re-dated");
406	        }
407	        refuseClosed(sheetId, claim.getDueBy());
408	        refuseRetired(person(sheetId, claim.getPersonId()), date);
409	        LocalDate old = claim.getDate();
410	        return rollup.tracking(sheetId, user, () -> {
411	            Person person = person(sheetId, claim.getPersonId());
412	            claim.setDate(date);
413	            Claim saved = claims.saveAndFlush(claim);
414	            audit.recordOnCommit(record("CLAIM_REDATED", sheetId, user, person, saved)
415	                    + " old=" + old + " new=" + date);
416	            return saved;
417	        });
418	    }
