425	    /** Split an amount (above 0.00 and below the claim's amount) off an open claim: it keeps the rest
426	     *  of its amount and loses any figure a statement bound it to, and a new open claim of the amount,
427	     *  the same date and note, the next number, opened by the user and due by the terms in force on
428	     *  the date, is listed as its person's newest claim. Refused when the claim is not open (or is
429	     *  deferred), its period is closed, the amount is out of range, or the permission matrix does not
430	     *  allow the user's role to open a claim. */
431	    @Transactional
432	    public Split split(String sheetId, String user, long claimId, BigDecimal part) {
433	        Claim claim = lock(sheetId, claimId);
434	        refuseClosed(sheetId, claim.getDueBy());
435	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
436	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an open claim that is not deferred can be split");
437	        }
438	        if (!roles.may(sheetId, user, "open")) {
439	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
440	        }
441	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
442	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
443	                    "The amount split off must be above 0.00 and below the claim's amount");
444	        }
445	        return rollup.tracking(sheetId, user, () -> {
446	            Person person = person(sheetId, claim.getPersonId());
447	            LocalDate dueBy = dueBy(sheetId, person, claim.getDate());
448	            Claim draft = claim.splitOff(part, nextNumber(sheetId, dueBy), user, dueBy);
449	            logStatus(sheetId, user, person, draft);
450	            Claim original = claims.saveAndFlush(claim);
451	            Claim split = claims.saveAndFlush(draft);
452	            audit.recordOnCommit(record("CLAIM_SPLIT", sheetId, user, person, original) + " into=" + split.getNumber());
453	            audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, split));
454	            return new Split(original, split);
455	        });
456	    }
