458	    /** The pending claim a steward approves or rejects, locked; refused when it is not pending, the
459	     *  user is not a steward, or its period is closed. */
460	    private Claim lockPending(String sheetId, String user, long claimId) {
461	        Claim claim = lock(sheetId, claimId);
462	        refuseClosed(sheetId, claim.getDueBy());
463	        if (claim.getStatus() != ClaimStatus.PENDING) {
464	            throw new ResponseStatusException(HttpStatus.CONFLICT,
465	                    "Only a PENDING claim can be approved or rejected");
466	        }
467	        if (!SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
468	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
469	                    "Only a steward can approve or reject a claim");
470	        }
471	        return claim;
472	    }
