489	    /** The number for a claim due by the day opened now: under period numbering, the next in its period
490	     *  (<period name>-<n>), or for one in no period the next X-<n>; otherwise the next on the sheet. */
491	    private String nextNumber(String sheetId, LocalDate dueBy) {
492	        if (!sheets.periodNumbering(sheetId)) {
493	            return String.valueOf(sheets.nextClaimNumber(sheetId));
494	        }
495	        return periods.findOn(sheetId, dueBy)
496	                .map(p -> {
497	                    periods.advanceClaimNumber(p.getId());
498	                    return p.getName() + "-" + periods.lastClaimNumber(p.getId());
499	                })
500	                .orElseGet(() -> "X-" + sheets.nextUnperiodNumber(sheetId));
501	    }
