503	    /** The claim a claim of the amount corrects: none for an amount of 0.00 or more; for a correction
504	     *  (a negative amount), the one of the number given, which must be a settled claim of the person,
505	     *  or else it is refused. */
506	    private Claim corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
507	        if (amount.signum() >= 0) {
508	            return null;
509	        }
510	        return (corrects == null ? Optional.<Claim>empty()
511	                : claims.findBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED))
512	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST,
513	                        "A negative amount must correct a settled claim of the same person"));
514	    }
