516	    /** Refuse a change to a claim due by the day when the day falls inside a closed period. */
517	    private void refuseClosed(String sheetId, LocalDate day) {
518	        if (periods.closedOn(sheetId, day)) {
519	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's period is closed");
520	        }
