523	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit in force on its today; a claim with
524	     *  no due (n/a) is within any limit, and a steward settles anything. */
525	    private boolean overClerkLimit(String sheetId, String user, Claim claim) {
526	        BigDecimal limit = sheets.clerkLimit(sheetId);
527	        if (limit == null || SheetRole.STEWARD.equals(roles.roleOf(sheetId, user))) {
528	            return false;
529	        }
530	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
531	        return due != null && due.compareTo(limit) > 0;
532	    }
