534	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof
535	     *  threshold in force on the claim's date; a claim with no due (n/a) and a sheet with no threshold
536	     *  need none. */
537	    private void refuseUnproved(String sheetId, Claim claim) {
538	        BigDecimal threshold = sheets.proofThreshold(sheetId, claim.getDate());
539	        if (threshold == null || claim.getProofs() > 0) {
540	            return;
541	        }
542	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
543	        if (due != null && due.compareTo(threshold) > 0) {
544	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
545	                    "A claim whose due is above the proof threshold needs a proof first");
546	        }
547	    }
