549	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in
550	     *  force on the claim's date; a claim with no due (n/a) and a sheet with no threshold need none. */
551	    private void refuseUnnoted(String sheetId, Claim claim) {
552	        BigDecimal threshold = sheets.noteThreshold(sheetId, claim.getDate());
553	        if (threshold == null || (claim.getNote() != null && !claim.getNote().isBlank())) {
554	            return;
555	        }
556	        BigDecimal due = dues.figure(sheetId, person(sheetId, claim.getPersonId()), claim);
557	        if (due != null && due.compareTo(threshold) > 0) {
558	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
559	                    "A claim whose due is above the note threshold needs a note before it is opened");
560	        }
561	    }
