563	    /** Refuse a claim of the person dated after the day they are retired from. */
564	    private static void refuseRetired(Person person, LocalDate day) {
565	        if (person.getRetiredFrom() != null && day.isAfter(person.getRetiredFrom())) {
566	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
567	                    "A claim cannot be dated after the person's retirement");
568	        }
