571	    /** The day a claim of the person dated on the day is due by: its date plus the first of the
572	     *  person's own terms, their grade's and the sheet's, each as in force on the day. */
573	    private LocalDate dueBy(String sheetId, Person person, LocalDate on) {
574	        Integer own = person.getTerms();
575	        return on.plusDays(own != null ? own : sheets.termsFor(sheetId, person.gradeOn(on), on));
